LANGAPP_PACKS.course["en-es"].STORIES={"greetings":{"title":"Hola, Max","tr":"Hi, Max","lines":[["Buenas tardes, señora. ¿Cómo está usted?","Good afternoon, ma'am. How are you?","Ana"],["Muy bien, gracias. ¿Y tú?","Very well, thank you. And you?","Señora"],["Bien, gracias. Me llamo Ana. ¿Cómo se llama usted?","Fine, thanks. My name is Ana. What's your name?","Ana"],["Me llamo Rosa. Mucho gusto, Ana.","My name is Rosa. Nice to meet you, Ana.","Señora"],["Mucho gusto, señora Rosa. Disculpe, ¿el perro es de usted?","Nice to meet you, Mrs. Rosa. Excuse me, is the dog yours?","Ana"],["Sí. Se llama Max.","Yes. His name is Max.","Señora"],["¡Hola, Max!","Hi, Max!","Ana"],["¡Hola, Ana! ¿Cómo estás?","Hi, Ana! How are you?","Diego"],["Muy bien, Diego. ¿Y tú?","Very well, Diego. And you?","Ana"],["¡Hola, hijo!","Hi, son!","Señora"],["Sí, Ana, Diego es mi hijo. Y Max es mi perro.","Yes, Ana, Diego is my son. And Max is my dog.","Señora"],["¡Mucho gusto, Max! Hasta luego, señora.","Nice to meet you, Max! See you later, ma'am.","Ana"],["Adiós, Ana.","Bye, Ana.","Diego"]],"qs":[{"q":"Who is the woman to Diego?","o":["His mother","His teacher","His neighbor","His boss"]},{"q":"Who or what is Max?","o":["The woman's dog","Diego's little brother","The café waiter","Ana's cat"]},{"q":"Who asks for a name first?","o":["Ana","The woman","Diego","Nobody does"]}]},"gender":{"title":"La foto de la familia","tr":"The family photo","lines":[["Hola, Lucía. ¿Es una foto?","Hi, Lucía. Is that a photo?","Diego"],["Sí, es la foto de mi familia.","Yes, it's the photo of my family.","Lucía"],["Ella es mi madre, y él es mi padre.","She's my mother, and he's my father.","Lucía"],["¿Y los niños?","And the boys?","Diego"],["Son mis hermanos, Mateo y Javier.","They're my brothers, Mateo and Javier.","Lucía"],["¿Y la mujer con el perro?","And the woman with the dog?","Diego"],["Es mi abuela. El perro se llama Max.","She's my grandmother. The dog's name is Max.","Lucía"],["¿Tus abuelos viven con ustedes?","Do your grandparents live with you?","Diego"],["Sí, mis abuelos viven en la casa con mis padres.","Yes, my grandparents live in the house with my parents.","Lucía"],["¿Y ella? ¿Es tu tía?","And her? Is she your aunt?","Diego"],["No, es mi hermana mayor, Sofía.","No, she's my older sister, Sofía.","Lucía"],["¿Sofía? ¡Sofía es mi amiga!","Sofía? Sofía is my friend!","Diego"],["¿Sí? ¿Tu amiga es mi hermana?","Really? Your friend is my sister?","Lucía"]],"qs":[{"q":"Who shares the house with Lucía's parents?","o":["Her grandparents","Her aunt and uncle","Diego's family","Only her sister"]},{"q":"Who is holding the dog in the picture?","o":["Lucía's grandmother","Lucía's mother","Lucía's aunt","Lucía's older sister"]},{"q":"What surprises the two at the end?","o":["Diego already knows Lucía's sister","Lucía's aunt lives with Diego","The dog belongs to Diego","Lucía has no brothers"]}]},"articles":{"title":"Unos tacos de pollo","tr":"Some chicken tacos","lines":[["Buenas tardes. ¿Me da un café, por favor?","Good afternoon. Can I have a coffee, please?","Diego"],["Sí. ¿Y algo para comer?","Sure. And something to eat?","Señora"],["¿Qué me recomienda?","What do you recommend?","Diego"],["Los tacos de pollo. ¡Son muy ricos!","The chicken tacos. They're very good!","Señora"],["¿Pica?","Is it spicy?","Diego"],["Sí, pica mucho.","Yes, it's very spicy.","Señora"],["Unos tacos de pollo y una quesadilla, por favor.","Some chicken tacos and a quesadilla, please.","Diego"],["¡Pica mucho! Un vaso de agua, por favor.","It's really spicy! A glass of water, please.","Diego"],["¿Agua de jamaica?","Hibiscus water?","Señora"],["Sí, por favor. ¡Me gusta el agua de jamaica!","Yes, please. I like hibiscus water!","Diego"],["La cuenta, por favor.","The check, please.","Diego"],["Es tu primera vez aquí, ¿no?","It's your first time here, isn't it?","Señora"],["Sí, pero no es la primera vez con tacos. ¡Muy ricos, gracias!","Yes, but it's not my first time with tacos. Very good, thanks!","Diego"]],"qs":[{"q":"What problem does Diego have with the food?","o":["It is very hot and spicy","It is cold","It has no chicken in it","It costs too much"]},{"q":"What does Diego ask for to help with the tacos?","o":["Hibiscus water","A cold beer","Another coffee","A glass of milk"]},{"q":"Why does Diego order the chicken tacos?","o":["The woman recommends them","He always eats them","They are the cheapest","His friend wants them"]}]},"ser":{"title":"¿Eres estudiante?","tr":"Are you a student?","lines":[["Hola. Me llamo Mateo. ¿Cómo te llamas?","Hi. My name is Mateo. What's your name?","Mateo"],["Me llamo Valeria. Mucho gusto.","My name is Valeria. Nice to meet you.","Valeria"],["¿De dónde eres?","Where are you from?","Mateo"],["Soy de Chicago, pero ahora vivo en Monterrey.","I'm from Chicago, but now I live in Monterrey.","Valeria"],["¡Hablas muy bien español!","You speak Spanish very well!","Mateo"],["Gracias. Hablo inglés y español.","Thanks. I speak English and Spanish.","Valeria"],["Yo soy de Guadalajara. Somos estudiantes aquí, ¿no?","I'm from Guadalajara. We're students here, right?","Mateo"],["No, yo no soy estudiante.","No, I'm not a student.","Valeria"],["¿Eres enfermera?","Are you a nurse?","Mateo"],["No. Soy la maestra de español.","No. I'm the Spanish teacher.","Valeria"],["¿Usted es la maestra? ¡Perdón, maestra!","You are the teacher? Sorry, teacher!","Mateo"],["Está bien, Mateo. Ellos son mis estudiantes, y tú eres mi estudiante.","It's fine, Mateo. They are my students, and you're my student.","Valeria"]],"qs":[{"q":"What does Valeria do?","o":["She teaches Spanish","She works as a nurse","She studies with Mateo","She is a doctor"]},{"q":"Where does Valeria live these days?","o":["In Monterrey","In Chicago","In Guadalajara","In Puebla"]},{"q":"Why does Mateo say sorry?","o":["He talked to his teacher like a classmate","He forgot Valeria's name","He spoke English to her","He said she was from Chicago"]}]},"adjectives":{"title":"Un regalo en el mercado","tr":"A gift at the market","lines":[["Busco un regalo para mi madre.","I'm looking for a gift for my mother.","Lucía"],["¿Una camisa? Las camisas son baratas aquí.","A shirt? The shirts are cheap here.","Diego"],["No, mi madre tiene muchas camisas.","No, my mother has a lot of shirts.","Lucía"],["Tengo faldas blancas, vestidos verdes y un suéter rojo.","I have white skirts, green dresses and a red sweater.","Señora"],["Me encanta el vestido verde. ¿Es caro?","I love the green dress. Is it expensive?","Lucía"],["Son ochocientos pesos.","It's eight hundred pesos.","Señora"],["¡Es muy caro! ¿Y el suéter rojo?","That's very expensive! And the red sweater?","Lucía"],["El suéter rojo es más barato, pero es grande.","The red sweater is cheaper, but it's big.","Señora"],["Tu madre es alta, ¿no?","Your mother is tall, right?","Diego"],["Sí, es alta. Lo llevo. ¿Aceptan tarjeta?","Yes, she's tall. I'll take it. Do you accept cards?","Lucía"],["Sí, tarjeta o efectivo.","Yes, card or cash.","Señora"],["¿Y el vestido verde?","And the green dress?","Diego"],["¡Lo llevo! El vestido verde es un regalo para mí.","I'll take it! The green dress is a gift for me.","Lucía"]],"qs":[{"q":"What does Lucía get for her mother?","o":["The big red sweater","The green dress","A white skirt","A pair of shoes"]},{"q":"Why doesn't Lucía buy her mother a shirt?","o":["Her mother already has plenty","The shirts cost too much","There are no red ones","Diego doesn't like them"]},{"q":"What happens with the green dress?","o":["Lucía buys it for herself","Diego buys it for his mother","The woman lowers the price","Nobody buys it"]}]},"estar":{"title":"La farmacia está lejos","tr":"The pharmacy is far","lines":[["Disculpe, ¿dónde está la farmacia?","Excuse me, where is the pharmacy?","Elena"],["La farmacia está lejos. ¿Está usted bien?","The pharmacy is far. Are you all right?","Señora"],["Yo estoy bien, pero mi hijo está enfermo.","I'm fine, but my son is sick.","Elena"],["No somos de aquí. Estamos en el hotel Rosa.","We're not from here. We're at the Hotel Rosa.","Elena"],["El hotel Rosa está cerca. Hay una farmacia enfrente del hotel.","The Hotel Rosa is close. There's a pharmacy across from the hotel.","Señora"],["¿Enfrente del hotel? ¿Dónde?","Across from the hotel? Where?","Elena"],["Siga derecho dos cuadras y gire a la izquierda en el semáforo.","Go straight two blocks and turn left at the traffic light.","Señora"],["La farmacia está en la esquina, al lado del banco.","The pharmacy is on the corner, next to the bank.","Señora"],["¡Muchas gracias!","Thank you very much!","Elena"],["Elena está en la esquina.","Elena is on the corner."],["La farmacia está allí, enfrente de su hotel.","The pharmacy is there, across from her hotel."],["¡Está enfrente de mi hotel! Estoy muy cansada.","It's right across from my hotel! I'm very tired.","Elena"]],"qs":[{"q":"Why does Elena need a pharmacy?","o":["Her son is ill","She feels sick herself","She wants a city map","Her husband is tired"]},{"q":"What must Elena do at the traffic light?","o":["Turn left","Turn right","Cross the street","Take a bus"]},{"q":"What does Elena discover at the end?","o":["The pharmacy faces her own hotel","The pharmacy is closed","She is at the wrong bank","Her hotel is far away"]}]},"ser-estar":{"title":"La fiesta en el parque","tr":"The party in the park","lines":[["¿Estás listo, Javier? La fiesta empieza en diez minutos.","Are you ready, Javier? The party starts in ten minutes.","Sofía"],["No estoy listo. Estoy cansado y tengo sueño.","I'm not ready. I'm tired and sleepy.","Javier"],["¿Dónde es la fiesta?","Where is the party?","Javier"],["La fiesta es en el parque. El parque está cerca.","The party is in the park. The park is close.","Sofía"],["Pero yo soy aburrido, Sofía.","But I'm boring, Sofía.","Javier"],["No eres aburrido. ¡Estás aburrido porque estás en casa!","You're not boring. You're bored because you're at home!","Sofía"],["¿Y tú? ¿Por qué estás nerviosa?","And you? Why are you nervous?","Javier"],["Estoy nerviosa porque mañana tengo un examen.","I'm nervous because I have an exam tomorrow.","Sofía"],["¿Un examen? ¿Y la fiesta?","An exam? And the party?","Javier"],["Hoy es la fiesta. Mañana es el examen. ¡Vamos!","Today is the party. Tomorrow is the exam. Let's go!","Sofía"],["En el parque, Javier está muy contento.","In the park, Javier is very happy."],["Ya es tarde, pero Javier no está cansado.","It is already late, but Javier is not tired."],["¡Sofía, la fiesta no es aburrida!","Sofía, the party isn't boring!","Javier"]],"qs":[{"q":"What is worrying Sofía?","o":["A test the next day","The long walk to the park","A sick friend","Javier's bad mood"]},{"q":"How does Javier feel before the party?","o":["Tired and sleepy","Hungry and thirsty","Sad and angry","Late and in a hurry"]},{"q":"How has Javier changed by the end?","o":["He is happy and no longer tired","He wants to go home early","He is nervous about an exam","He thinks the party is boring"]}]},"hay":{"title":"No hay nada","tr":"There's nothing","lines":[["Hola, Pablo. ¡Es mi apartamento!","Hi, Pablo. This is my apartment!","Marta"],["¿Hay dos cuartos?","Are there two bedrooms?","Pablo"],["Sí, hay dos cuartos y un baño.","Yes, there are two bedrooms and a bathroom.","Marta"],["En la sala hay un sofá azul y tres sillas.","In the living room there's a blue sofa and three chairs.","Marta"],["¿Y la cocina?","And the kitchen?","Pablo"],["La cocina está aquí. Hay un refrigerador grande.","The kitchen is here. There's a big refrigerator.","Marta"],["Tengo sed. ¿Hay agua?","I'm thirsty. Is there any water?","Pablo"],["No hay agua. Y no hay leche.","There's no water. And there's no milk.","Marta"],["¿No hay nada?","There's nothing?","Pablo"],["No. El refrigerador es grande, pero no hay nada.","No. The refrigerator is big, but there's nothing in it.","Marta"],["¿Hay una tienda cerca?","Is there a store nearby?","Pablo"],["Sí, la tienda está en la esquina. Pero... ¿dónde están mis llaves?","Yes, the store is on the corner. But... where are my keys?","Marta"]],"qs":[{"q":"What furniture is in the living room?","o":["A blue sofa and three chairs","Two beds and a table","A big refrigerator","A sofa and two beds"]},{"q":"Why do they need to go out?","o":["The fridge is empty","They want a new sofa","Pablo wants to buy a gift","The bathroom is broken"]},{"q":"What problem comes up at the end?","o":["Marta can't find her keys","The store is closed","Pablo feels sick","The store is far away"]}]},"present":{"title":"Max está perdido","tr":"Max is lost","lines":[["Ana trabaja en una oficina en San Antonio.","Ana works in an office in San Antonio."],["Su esposo, Diego, es enfermero y trabaja en un hospital.","Her husband, Diego, is a nurse and works in a hospital."],["Ana y Diego viven en un apartamento cerca del parque.","Ana and Diego live in an apartment near the park."],["Hola, ¿usted habla inglés?","Hi, do you speak English?","Max"],["Sí, hablo inglés y español.","Yes, I speak English and Spanish.","Ana"],["Gracias. Estoy perdido. Busco el hospital.","Thanks. I'm lost. I'm looking for the hospital.","Max"],["Mi esposo trabaja en el hospital. Está cerca.","My husband works at the hospital. It's close.","Ana"],["¿Ustedes viven aquí?","Do you all live here?","Max"],["Sí, vivimos en San Antonio. ¿Y usted?","Yes, we live in San Antonio. And you?","Ana"],["Vivo en Chicago, pero hoy trabajo en el hospital con su esposo.","I live in Chicago, but today I work at the hospital with your husband.","Max"],["En la tarde, Diego, Max y Ana comen tacos en la taquería.","In the afternoon, Diego, Max and Ana eat tacos at the taco shop."]],"qs":[{"q":"Why does Max talk to Ana?","o":["He is lost and needs directions","He wants to practice his Spanish","He is waiting for a taxi there","He works in the same office"]},{"q":"What does Max say about where he lives?","o":["He lives in another city","He lives near the park","He lives in Ana's building","He lives at the hospital"]},{"q":"What is the surprise in Max's last answer?","o":["He works with Ana's husband today","He is Ana's brother from Chicago","He is the new boss at Ana's office","He is the owner of the taco shop"]}]},"questions":{"title":"¿Quién es ella?","tr":"Who is she?","lines":[["Javier está en un café con su amiga Lucía.","Javier is in a café with his friend Lucía."],["En una mesa hay una mujer con libros.","At one table there is a woman with books."],["Lucía, ¿quién es ella?","Lucía, who is she?","Javier"],["¿Por qué no hablas con ella?","Why don't you talk to her?","Lucía"],["Hola, ¿cómo te llamas?","Hi, what's your name?","Javier"],["Me llamo Isabel. ¿Y tú?","My name is Isabel. And you?","Isabel"],["Javier. ¿Qué estudias?","Javier. What are you studying?","Javier"],["Estudio inglés porque tengo un examen el lunes.","I'm studying English because I have an exam on Monday.","Isabel"],["¿Y por qué estudias aquí y no en casa?","And why do you study here and not at home?","Javier"],["Porque en mi casa están mis padres, mis hermanas y dos perros.","Because my parents, my sisters and two dogs are at my house.","Isabel"],["¿Dónde trabajas tú? ¿Hablas inglés?","Where do you work? Do you speak English?","Isabel"],["Trabajo en un banco. Sí, hablo inglés.","I work in a bank. Yes, I speak English.","Javier"],["¡Qué bien! Entonces, ¿hablamos en inglés?","How nice! So, shall we talk in English?","Isabel"],["Hablo inglés, pero muy poco.","I speak English, but very little.","Javier"]],"qs":[{"q":"Why is Isabel studying at the café?","o":["Her home is full of family and pets","The café is close to her school","She works at the café on Mondays","Her friends study there with her"]},{"q":"Who pushes Javier to talk to Isabel?","o":["Lucía","Isabel's sister","The waiter","Nobody, he decides alone"]},{"q":"What is the surprise at the end?","o":["Javier speaks very little English","Isabel already knows Javier","Javier also has an exam on Monday","Isabel works at Javier's bank"]}]},"numbers":{"title":"El sombrero de la abuela","tr":"Grandma's hat","lines":[["Son las diez y media y Diego está en el mercado.","It's half past ten and Diego is at the market."],["Su abuela tiene una fiesta hoy.","His grandmother is having a party today."],["Oye, ¿cuánto cuesta este sombrero?","Hey, how much is this hat?","Diego"],["Cuesta quinientos pesos.","It costs five hundred pesos.","María"],["¿Quinientos? Es mucho. Tengo solo trescientos veinte pesos.","Five hundred? That's a lot. I only have three hundred and twenty pesos.","Diego"],["Está bien. Son trescientos veinte.","All right. That's three hundred and twenty.","María"],["A la una, Diego está en la fiesta con el regalo.","At one o'clock, Diego is at the party with the gift."],["¡Un sombrero! Gracias, Diego.","A hat! Thank you, Diego.","Abuela"],["¿Cuánto cuesta? ¿Cien pesos?","How much is it? A hundred pesos?","Abuela"],["No, abuela. Cuesta trescientos veinte pesos.","No, Grandma. It costs three hundred and twenty pesos.","Diego"],["¿Trescientos veinte? Mi amiga María vende sombreros en el mercado.","Three hundred and twenty? My friend María sells hats at the market.","Abuela"],["Sus sombreros cuestan doscientos pesos.","Her hats cost two hundred pesos.","Abuela"]],"qs":[{"q":"How much does Diego pay for the hat?","o":["320 pesos","500 pesos","100 pesos","200 pesos"]},{"q":"When is Diego at the party?","o":["At one o'clock","At half past ten","At half past three","At a quarter past eight"]},{"q":"What does the grandmother's last comment suggest?","o":["Diego paid too much for the hat","She already has the same hat","She doesn't like hats at all","María gave Diego a good price"]}]},"possessives":{"title":"¿Quiénes son?","tr":"Who are they?","lines":[["Sofía y Pablo están en la sala con una foto.","Sofía and Pablo are in the living room with a photo."],["¿Quiénes son estas personas?","Who are these people?","Pablo"],["Es mi familia. Estos son mis padres.","It's my family. These are my parents.","Sofía"],["Mis padres son de Puebla, pero viven en Monterrey.","My parents are from Puebla, but they live in Monterrey.","Sofía"],["¿Y esa mujer alta?","And that tall woman?","Pablo"],["Es mi hermana Elena. Esos niños son sus hijos.","That's my sister Elena. Those kids are her children.","Sofía"],["Esta casa es muy grande. ¿Es de tus padres?","This house is very big. Is it your parents'?","Pablo"],["Sí. Nuestra casa es pequeña, pero su casa es muy grande.","Yes. Our house is small, but their house is very big.","Sofía"],["¿Y esa señora de la camisa roja?","And that lady in the red shirt?","Pablo"],["Es mi tía Marta. Ese perro es su perro.","That's my aunt Marta. That dog is her dog.","Sofía"],["¿Tu tía? ¡Esa señora es mi jefa!","Your aunt? That lady is my boss!","Pablo"],["¡No! ¿Marta es tu jefa?","No way! Marta is your boss?","Sofía"]],"qs":[{"q":"Where do Sofía's parents live now?","o":["In Monterrey","In Puebla","In a small house with Sofía","With Marta"]},{"q":"Who are the children in the photo?","o":["Elena's kids","Sofía's kids","Marta's kids","Pablo's kids"]},{"q":"Why is Pablo surprised?","o":["Sofía's aunt is his boss","Sofía's sister is his teacher","The dog in the photo is his","He knows the big house well"]}]},"irregular":{"title":"Un sábado en la playa","tr":"A Saturday at the beach","lines":[["Lucía, ¿qué haces el sábado?","Lucía, what are you doing on Saturday?","Mateo"],["Nada. ¿Por qué?","Nothing. Why?","Lucía"],["Hace sol y hace calor. Voy a la playa con mis hermanos.","It's sunny and hot. I'm going to the beach with my brothers.","Mateo"],["¿Tienes tiempo? ¿Vamos?","Do you have time? Shall we go?","Mateo"],["¡Sí! Tengo tiempo.","Yes! I have time.","Lucía"],["El sábado, Mateo y Lucía van a la playa en autobús.","On Saturday, Mateo and Lucía go to the beach by bus."],["Pero en la playa no hace sol.","But at the beach it isn't sunny."],["¿Qué tiempo hace? Está nublado y hace frío.","What's the weather like? It's cloudy and cold.","Lucía"],["Sí, y está lloviendo.","Yes, and it's raining.","Mateo"],["Tengo frío y tengo hambre.","I'm cold and I'm hungry.","Lucía"],["Yo también. ¿Qué hacemos?","Me too. What do we do?","Mateo"],["Hay una taquería allí.","There's a taco shop over there.","Lucía"],["En la taquería están los hermanos de Mateo, con tacos para todos.","In the taco shop are Mateo's brothers, with tacos for everyone."]],"qs":[{"q":"Why does Mateo invite Lucía to the beach?","o":["He thinks the weather is sunny and hot","It is Lucía's birthday on Saturday","Lucía's family lives near the beach","They have a class at the beach"]},{"q":"What is the weather like when they arrive?","o":["Cloudy, cold and rainy","Sunny and very hot","Windy but warm","Cold but sunny"]},{"q":"Who is waiting in the taco shop?","o":["Mateo's brothers","Lucía's parents","Their teacher","Nobody, it is closed"]}]},"stem-change":{"title":"Pablo está enfermo","tr":"Pablo is sick","lines":[["Es domingo y Pablo está enfermo en casa.","It's Sunday and Pablo is sick at home."],["Pablo, ¿cómo te sientes?","Pablo, how do you feel?","Elena"],["Mal. Tengo fiebre y tos.","Bad. I have a fever and a cough.","Pablo"],["¿Quieres ir al médico?","Do you want to go to the doctor?","Elena"],["No, prefiero dormir. Quiero descansar en casa.","No, I prefer to sleep. I want to rest at home.","Pablo"],["Puedo ir a la farmacia. ¿Quieres medicina?","I can go to the pharmacy. Do you want medicine?","Elena"],["Sí, por favor. Pero no puedo tomar penicilina. Soy alérgico.","Yes, please. But I can't take penicillin. I'm allergic.","Pablo"],["En la farmacia, Elena pide pastillas para la gripa.","At the pharmacy, Elena asks for pills for the flu."],["Mi esposo tiene gripa. ¿Qué medicina me recomienda?","My husband has the flu. What medicine do you recommend?","Elena"],["A las seis, Elena está en casa con las pastillas.","At six, Elena is home with the pills."],["Pero Pablo no está en la cama.","But Pablo isn't in bed."],["Está en la cocina con una pizza y una cerveza.","He's in the kitchen with a pizza and a beer."],["¿Qué? ¡Tengo hambre!","What? I'm hungry!","Pablo"]],"qs":[{"q":"Why must Elena be careful with the medicine?","o":["Pablo is allergic to penicillin","The pharmacy closes at six","Pablo can't swallow pills","The doctor said no medicine"]},{"q":"What does Pablo choose instead of seeing a doctor?","o":["Staying home to sleep","Going to the pharmacy","Calling an ambulance","Eating at a restaurant"]},{"q":"What does Elena find when she gets home?","o":["Pablo eating pizza in the kitchen","Pablo asleep in his bed","A doctor in the living room","Pablo waiting at the door"]}]},"gustar":{"title":"¿Te gusta el café?","tr":"Do you like coffee?","lines":[["Carlos y María están en un café.","Carlos and María are in a café."],["María, ¿te gusta el fútbol?","María, do you like soccer?","Carlos"],["No, no me gusta el fútbol. Me gusta el básquetbol.","No, I don't like soccer. I like basketball.","María"],["A mí también. ¿Y te gusta bailar?","Me too. And do you like to dance?","Carlos"],["Sí, me encanta bailar. Me gusta mucho la música.","Yes, I love to dance. I really like music.","María"],["A mí no. No me gusta bailar.","Not me. I don't like to dance.","Carlos"],["¿Te gustan las películas?","Do you like movies?","María"],["Sí, me encantan las películas de miedo.","Yes, I love horror movies.","Carlos"],["A mí no me gustan. Tengo miedo.","I don't like them. I get scared.","María"],["¿Te gusta el café?","Do you like coffee?","Carlos"],["No, no me gusta el café.","No, I don't like coffee.","María"],["A mí tampoco.","Me neither.","Carlos"],["Entonces... ¿por qué estamos en un café?","So... why are we in a café?","María"]],"qs":[{"q":"Which sport do both of them like?","o":["Basketball","Soccer","Tennis","Baseball"]},{"q":"Why doesn't María like the movies Carlos loves?","o":["They scare her","They are too long","She prefers music","They are in English"]},{"q":"What is funny at the end?","o":["Neither likes coffee, yet they're in a café","Both love dancing, yet they never dance","Neither likes soccer, yet they're at a game","Both hate movies, yet they're at a cinema"]}]},"reflexive":{"title":"Un lunes muy temprano","tr":"A very early Monday","lines":[["Me llamo Luis y tengo clase a las ocho.","My name is Luis and I have class at eight."],["Los lunes me levanto temprano, a las seis.","On Mondays I get up early, at six."],["Me baño a las seis y cuarto y me lavo los dientes.","I shower at a quarter past six and I brush my teeth."],["Luego me visto y desayuno con mi hermano.","Then I get dressed and have breakfast with my brother."],["Mi hermano se llama Diego y se levanta tarde.","My brother's name is Diego and he gets up late."],["Hoy no me despierto a las seis.","Today I don't wake up at six."],["Me despierto a las siete y media.","I wake up at half past seven."],["¡Tengo prisa! No desayuno.","I'm in a hurry! I don't have breakfast."],["Me visto en dos minutos y llego a la escuela a las ocho.","I get dressed in two minutes and I get to school at eight."],["Pero en la escuela no hay estudiantes.","But there are no students at the school."],["Luis, hoy es domingo. ¿Por qué te levantas temprano?","Luis, today is Sunday. Why are you getting up early?","Diego"],["Entonces voy a casa y me acuesto.","So I go home and go to bed."]],"qs":[{"q":"What time does Luis normally get up on Mondays?","o":["At six","At half past seven","At eight","At a quarter past six"]},{"q":"What does Luis skip today because he is in a hurry?","o":["Breakfast","His shower","Brushing his teeth","Getting dressed"]},{"q":"Why are there no students at school?","o":["It is Sunday","Class starts at nine","The teacher is sick","Luis is at the wrong school"]}]},"prepositions":{"title":"El pasaporte de Javier","tr":"Javier's passport","lines":[["Es diciembre y Javier va a Guadalajara a la fiesta de su familia.","It's December and Javier is going to Guadalajara for his family's party."],["¿Vas al aeropuerto en taxi?","Are you going to the airport by taxi?","Marta"],["No, voy en metro. Es barato.","No, I'm going by subway. It's cheap.","Javier"],["Yo también voy al centro. ¿Voy contigo?","I'm going downtown too. Shall I go with you?","Marta"],["¡Claro! Vamos a pie a la estación del metro.","Sure! Let's walk to the subway station.","Javier"],["En el metro, Javier está nervioso.","On the subway, Javier is nervous."],["¿Dónde está mi pasaporte? No está en la maleta.","Where is my passport? It's not in the suitcase.","Javier"],["¿Está en tu chaqueta?","Is it in your jacket?","Marta"],["No. Está en casa. ¡No puedo viajar sin pasaporte!","No. It's at home. I can't travel without a passport!","Javier"],["Javier, tu pasaporte está aquí, conmigo.","Javier, your passport is here, with me.","Marta"],["¿Por qué está contigo?","Why do you have it?","Javier"],["Es de la mesa de tu cocina, con tu boleto.","It is from your kitchen table, along with your ticket.","Marta"],["¡Gracias por todo, Marta!","Thanks for everything, Marta!","Javier"]],"qs":[{"q":"How does Javier get to the airport?","o":["By subway","By taxi","In Marta's car","By bus"]},{"q":"Why is Javier going to Guadalajara?","o":["For a family party","For a work meeting","To study Spanish","For a beach vacation"]},{"q":"How does Marta have Javier's passport?","o":["He left it on his kitchen table","He gave it to her at the station","It fell out of his jacket","She works at the airport"]}]},"muy-mucho":{"title":"Mucho frío","tr":"Very cold","lines":[["Hoy hace mucho frío en Chicago.","It's very cold in Chicago today."],["Ana está muy cansada porque trabaja mucho.","Ana is very tired because she works a lot."],["Diego, ¿tienes frío?","Diego, are you cold?","Ana"],["No, pero tengo mucha hambre.","No, but I'm very hungry.","Diego"],["¿Quieres tacos? Hay una taquería muy cerca.","Do you want tacos? There's a taquería very close.","Ana"],["Sí, me gusta mucho la taquería de don Antonio.","Yes, I like Don Antonio's taquería a lot.","Diego"],["En la taquería hay mucha gente.","There are a lot of people in the taquería."],["Diego pide cinco tacos y una sopa.","Diego orders five tacos and a soup."],["Ana pide un té con mucho azúcar.","Ana orders a tea with a lot of sugar."],["¿Cinco tacos? ¡Es mucho!","Five tacos? That's a lot!","Ana"],["Sí, pero hace frío y tengo mucha hambre.","Yes, but it's cold and I'm very hungry.","Diego"],["Luego, Ana come tres tacos de Diego.","Then Ana eats three of Diego's tacos."]],"qs":[{"q":"Why is Ana very tired?","o":["She works a lot","It's very cold outside","She didn't sleep well","She walked a long way"]},{"q":"What does Ana order for herself?","o":["A tea with a lot of sugar","Five tacos and a soup","A coffee with milk","A soup and a tea"]},{"q":"What happens at the end?","o":["Ana eats three of Diego's tacos","Diego can't finish his soup","Ana orders five more tacos","Diego gives his tea to Ana"]}]},"connectors":{"title":"¿Café o té?","tr":"Coffee or tea?","lines":[["Sofía e Isabel trabajan en un café en Monterrey.","Sofía and Isabel work in a café in Monterrey."],["Hoy hay siete u ocho personas, y Mateo, un estudiante, también está allí.","Today there are seven or eight people, and Mateo, a student, is there too."],["¿Quieres café o té?","Do you want coffee or tea?","Isabel"],["Café con leche, porque tengo mucho sueño.","Coffee with milk, because I'm very sleepy.","Mateo"],["Perdón, hoy no hay leche.","Sorry, there's no milk today.","Isabel"],["No me gusta el café sin leche.","I don't like coffee without milk.","Mateo"],["A mí tampoco.","Me neither.","Sofía"],["Entonces no quiero café, sino té.","Then I don't want coffee, but tea.","Mateo"],["¿Qué estudias, Mateo?","What are you studying, Mateo?","Sofía"],["Estudio inglés, porque mi familia vive en Chicago.","I'm studying English, because my family lives in Chicago.","Mateo"],["¡Mi familia también vive en Chicago!","My family lives in Chicago too!","Sofía"],["Mateo toma su té y habla con Sofía una hora.","Mateo drinks his tea and talks with Sofía for an hour."]],"qs":[{"q":"Why does Mateo end up not ordering coffee?","o":["There is no milk","The coffee is too expensive","He isn't sleepy anymore","Isabel recommends the tea"]},{"q":"Why is Mateo studying English?","o":["His family lives in Chicago","He works in a café","Sofía is his teacher","He wants to travel to Miami"]},{"q":"What surprises Sofía?","o":["Her family also lives in Chicago","Mateo is from Colombia","Isabel doesn't like coffee either","The café has eight customers"]}]},"directions":{"title":"¿Dónde está la farmacia?","tr":"Where is the pharmacy?","lines":[["Elena está en Oaxaca y le duele la cabeza.","Elena is in Oaxaca and she has a headache."],["Disculpe, ¿hay una farmacia por aquí?","Excuse me, is there a pharmacy around here?","Elena"],["Sí, pero está un poco lejos.","Yes, but it's a bit far.","Señora"],["Siga derecho dos cuadras y gire a la derecha.","Go straight for two blocks and turn right.","Señora"],["¿Cómo? ¿A la derecha o a la izquierda?","Sorry? To the right or to the left?","Elena"],["A la derecha. Está enfrente del banco, al lado de la iglesia.","To the right. It's across from the bank, next to the church.","Señora"],["Muchas gracias.","Thank you very much.","Elena"],["Elena camina dos cuadras.","Elena walks two blocks."],["Hay un banco y una iglesia, pero no hay farmacia.","There's a bank and a church, but there's no pharmacy."],["Elena pregunta a un policía.","Elena asks a police officer."],["Disculpe, ¿dónde está la farmacia?","Excuse me, where is the pharmacy?","Elena"],["Está muy cerca, señora. ¡Está a su izquierda!","It's very close, ma'am. It's on your left!","Policía"]],"qs":[{"q":"Why is Elena looking for a pharmacy?","o":["She has a headache","She has a fever","She needs a map","She works there"]},{"q":"Where is the pharmacy, according to the woman?","o":["Across from the bank, next to the church","Next to the bank, across from the church","Across from the hotel, next to the park","Next to the hotel, across from the bank"]},{"q":"What does the police officer tell her?","o":["It's right there on her left","It's far away on the right","It's closed today","She has to cross the street"]}]},"ir-a":{"title":"El sábado","tr":"On Saturday","lines":[["¿Qué vas a hacer el sábado, Javier?","What are you going to do on Saturday, Javier?","Lucía"],["Voy a viajar a Cancún con mi familia.","I'm going to travel to Cancún with my family.","Javier"],["¿Van a tomar el autobús?","Are you going to take the bus?","Lucía"],["No, vamos a ir al aeropuerto mañana temprano.","No, we're going to go to the airport early tomorrow.","Javier"],["Mi hermana va a comprar los boletos esta noche.","My sister is going to buy the tickets tonight.","Javier"],["¿Y qué van a hacer en Cancún?","And what are you going to do in Cancún?","Lucía"],["Vamos a comer tacos, bailar y descansar en la playa.","We're going to eat tacos, dance and rest on the beach.","Javier"],["¡Qué bien! Yo no voy a descansar.","How nice! I'm not going to rest.","Lucía"],["¿Por qué?","Why?","Javier"],["Porque voy a trabajar todo el fin de semana.","Because I'm going to work all weekend.","Lucía"],["Esa noche, Marta, la hermana de Javier, llama.","That night, Marta, Javier's sister, calls."],["Javier, no hay boletos para mañana. ¡Vamos a viajar el próximo sábado!","Javier, there are no tickets for tomorrow. We're going to travel next Saturday!","Marta"]],"qs":[{"q":"Who is going to buy the tickets?","o":["Javier's sister","Javier's parents","Lucía","Javier himself"]},{"q":"Why won't Lucía rest this weekend?","o":["She is going to work all weekend","She is going to travel to Cancún","She is going to visit her grandmother","She is going to study for an exam"]},{"q":"What problem comes up at the end?","o":["There are no tickets for tomorrow","The hotel in Cancún is full","Javier's sister is sick","The airport is closed on Saturday"]}]},"lo-la":{"title":"Me los llevo","tr":"I'll take them","lines":[["Pablo está en una tienda en Guadalajara.","Pablo is in a store in Guadalajara."],["Necesita zapatos negros para una fiesta.","He needs black shoes for a party."],["¿Los zapatos negros? Sí, los tenemos.","The black shoes? Yes, we have them.","María"],["¿Cuánto cuestan?","How much do they cost?","Pablo"],["Cuestan ochocientos pesos.","They cost eight hundred pesos.","María"],["Son un poco caros, pero los quiero. Me los llevo.","They're a bit expensive, but I want them. I'll take them.","Pablo"],["¿Y la camisa roja? ¿La quiere también?","And the red shirt? Do you want it too?","María"],["Sí, la compro. Aquí está mi tarjeta.","Yes, I'll buy it. Here's my card.","Pablo"],["Pablo busca su tarjeta, pero no la tiene.","Pablo looks for his card, but he doesn't have it."],["¿Mi tarjeta? ¡No la tengo!","My card? I don't have it!","Pablo"],["¿Tiene efectivo?","Do you have cash?","María"],["No, pero puedo llamar a mi esposa. La llamo ahora.","No, but I can call my wife. I'll call her now.","Pablo"],["Su esposa viene con la tarjeta, y ella también compra un vestido.","His wife comes with the card, and she buys a dress too."]],"qs":[{"q":"Why does Pablo need new shoes?","o":["For a party","For his job","For a trip","For a wedding"]},{"q":"What problem does Pablo have when he goes to pay?","o":["He doesn't have his card","The shirt is too expensive","The shoes are the wrong size","The store doesn't take cash"]},{"q":"What happens at the end?","o":["His wife brings the card and buys a dress","His wife pays over the phone","Pablo pays in cash after all","María lets him pay tomorrow"]}]},"preterite":{"title":"El fin de semana","tr":"The weekend","lines":[["¿Qué hiciste el fin de semana, Carlos?","What did you do on the weekend, Carlos?","Marta"],["El sábado fui a la playa con mis amigos.","On Saturday I went to the beach with my friends.","Carlos"],["¿Y qué comieron?","And what did you eat?","Marta"],["Comimos tacos y quesadillas en una taquería.","We ate tacos and quesadillas at a taquería.","Carlos"],["¿Y el domingo?","And on Sunday?","Marta"],["El domingo trabajé todo el día. ¿Y tú? ¿Trabajaste?","On Sunday I worked all day. And you? Did you work?","Carlos"],["No, no trabajé. Hablé con mi abuela y comí en su casa.","No, I didn't work. I talked with my grandmother and ate at her house.","Marta"],["¡Qué bien! ¿Ya comiste hoy?","How nice! Have you eaten today yet?","Carlos"],["Sí, ya comí.","Yes, I already ate.","Marta"],["Yo no. Anoche no comí y ahora tengo mucha hambre.","I haven't. Last night I didn't eat and now I'm very hungry.","Carlos"],["Entonces vamos a la taquería. ¡Yo pago!","Then let's go to the taquería. I'm paying!","Marta"],["Carlos comió seis tacos, y Marta, solo un café.","Carlos ate six tacos, and Marta, just a coffee."]],"qs":[{"q":"What did Carlos do on Saturday?","o":["He went to the beach with friends","He visited his grandmother","He worked all day","He went to a party in the city"]},{"q":"What did Marta do on the weekend?","o":["She ate at her grandmother's house","She worked all day on Sunday","She went to the beach","She ate at a taquería with friends"]},{"q":"Why is Carlos very hungry?","o":["He didn't eat last night","He worked all day today","He only had a coffee","He ran on the beach"]}]},"se":{"title":"Se rentan cuartos","tr":"Rooms for rent","lines":[["Luis busca un cuarto en Monterrey porque va a trabajar allí.","Luis is looking for a room in Monterrey because he's going to work there."],["En una casa hay un papel que dice: Se rentan cuartos.","On a house there's a sign that says: Rooms for rent."],["Buenas tardes. ¿Aquí se rentan cuartos?","Good afternoon. Are rooms for rent here?","Luis"],["Sí. Un cuarto cuesta tres mil pesos.","Yes. A room costs three thousand pesos.","Señora"],["¿Se puede pagar con tarjeta?","Can you pay by card?","Luis"],["No, aquí solo se paga en efectivo.","No, here you only pay in cash.","Señora"],["Está bien. ¿Se puede comer en el cuarto?","That's fine. Can you eat in the room?","Luis"],["No, en el cuarto no se puede comer. Aquí se come en la cocina, a las nueve.","No, you can't eat in the room. Here people eat in the kitchen, at nine.","Señora"],["¿A las nueve? Es tarde.","At nine? That's late.","Luis"],["Sí, en esta casa se come tarde. ¿Cómo se escribe su nombre?","Yes, in this house people eat late. How do you spell your name?","Señora"],["Luis Ruiz.","Luis Ruiz.","Luis"],["¿Luis Ruiz? ¡Mi esposo también se llama Luis Ruiz!","Luis Ruiz? My husband is also called Luis Ruiz!","Señora"]],"qs":[{"q":"How can Luis pay for the room?","o":["Only in cash","Only by card","In cash or by card","With a check every month"]},{"q":"Where and when do people eat in the house?","o":["In the kitchen, at nine","In their rooms, at nine","In the kitchen, at seven","In the garden, at eight"]},{"q":"What surprises the woman at the end?","o":["Her husband has the same name as Luis","Luis already lives in Monterrey","Luis wants to rent two rooms","Luis knows her son from work"]}]},"caribbean":{"title":"En el colmado","tr":"At the corner store","lines":[["Wilson vive en Santiago y trabaja en un colmado.","Wilson lives in Santiago and works in a corner store."],["Una tarde, Yanelis entra al colmado.","One afternoon, Yanelis comes into the store."],["¡Hola, Yanelis! ¿Cómo tú estás?","Hi, Yanelis! How are you?","Wilson"],["Estoy muy cansada, Wilson. La guagua no llegó.","I'm very tired, Wilson. The bus didn't come.","Yanelis"],["¿Y qué tú quieres hoy?","And what do you want today?","Wilson"],["Quiero un chin de café, pan y habichuelas.","I want a little coffee, bread and beans.","Yanelis"],["¿Para los niños?","For the kids?","Wilson"],["Sí, los niños están en la casa y tienen hambre.","Yes, the kids are at home and they're hungry.","Yanelis"],["Wilson le da el café, el pan y las habichuelas.","Wilson gives her the coffee, the bread and the beans."],["¿Cuánto es?","How much is it?","Yanelis"],["Nada. Hoy es tu cumpleaños, ¿no?","Nothing. Today is your birthday, isn't it?","Wilson"],["¡Sí! ¿Y cómo tú sabes esa cosa?","Yes! And how do you know that?","Yanelis"],["Porque tu mamá habló conmigo ayer.","Because your mom talked to me yesterday.","Wilson"]],"qs":[{"q":"Why is Yanelis so tired?","o":["The bus didn't come","She worked all night","Her kids are sick","She walked from the beach"]},{"q":"Who is the food for?","o":["Her kids at home","Her mother","Wilson's family","A party at work"]},{"q":"Why doesn't Wilson charge her?","o":["It's her birthday","She is his sister","The store is closing","She paid yesterday"]}]}};
